284	void ZipArchive::beginEntrySession(void) {
285	    entrySession = std::make_shared<ZipEntrySession>();
286	    //the compression configuration staged on individual entries belongs to the opening
287	    //it was made in: a new opening never inherits the levels recorded previously
288	    entryCompressionMethods.clear();
289	    entryCompressionLevels.clear();
290	}
