431	bool ZipArchive::open(OpenMode om, bool checkConsistency) {
432	    if (isOpen()) { return om==mode; }
433	
434	    int zipFlag = 0;
435	    if (om==ReadOnly) { zipFlag = 0; }
436	    else if (om==Write) { zipFlag = ZIP_CREATE; }
437	    else if (om==New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
438	    else { return false; }
439	
440	    if (checkConsistency) {
441	        zipFlag = zipFlag | ZIP_CHECKCONS;
442	    }
443	
444	    int errorFlag = 0;
445	    zipHandle = zip_open(path.c_str(), zipFlag, &errorFlag);
446	
447	    //error during opening of the file
448	    if (errorFlag!=ZIP_ER_OK) {
449	        zip_error_t error;
450	        zip_error_init_with_code(&error, errorFlag);
451	        Helper::callErrorHandlingCallback(&error, "unable to open archive: %s\n", errorHandlingCallback);
452	        zip_error_fini(&error);
453	
454	        zipHandle = nullptr;
455	        return false;
456	    }
457	
458	    if (zipHandle!=nullptr) {
459	#ifdef LIBZIPPP_WITH_ENCRYPTION
460	        if (isEncrypted()) {
461	            int result = zip_set_default_password(zipHandle, password.c_str());
462	            if (result!=0) {
463	                close();
464	                return false;
465	            }
466	        }
467	#endif
468	
469	        mode = om;
470	        beginEntrySession(); //entries created by this opening share this marker
471	        return true;
472	    }
473	
474	    return false;
475	}
