651	bool ZipArchive::setEntryCompressionConfig(ZipEntry& entry, CompressionMethod comp, libzippp_uint32 level) const {
652	    if (!isOpen()) { return false; }
653	    if (!isEntryUsable(entry)) { return false; }
654	    if (mode==ReadOnly) { return false; }
655	    const libzippp_uint16 comp_libzip = convertCompressionToLibzip(comp);
656	
657	    //libzip does not reject an out-of-range DEFLATE level: the documented range is
658	    //enforced beforehand so that a failure leaves both the entry and the archive untouched
659	    if (!isCompressionLevelApplicable(comp_libzip, level)) { return false; }
660	
661	    bool success = zip_set_file_compression(zipHandle, entry.index, compressionMethodToLibzip(comp_libzip), level)==0;
662	    if (success) {
663	        entry.compressionMethod = comp_libzip;
664	        entry.compressionLevel = level;
665	        //remember the staged configuration for this opening: libzip cannot report the
666	        //level back and reports ZIP_CM_DEFAULT as STORE in the current state
667	        entryCompressionMethods[entry.index] = comp_libzip;
668	        entryCompressionLevels[entry.index] = level;
669	    }
670	    return success;
671	}
672	
673	bool ZipArchive::setEntryCompressionMethod(ZipEntry& entry, CompressionMethod comp) const {
674	    if (!isOpen()) { return false; }
675	    if (!isEntryUsable(entry)) { return false; }
676	    if (mode==ReadOnly) { return false; }
677	
678	    //only the method changes: the level currently in effect for the entry is re-applied,
679	    //so a level staged through another copy of the entry is preserved
680	    libzippp_uint32 level = 0;
681	    map<libzippp_uint64, libzippp_uint32>::const_iterator it = entryCompressionLevels.find(entry.index);
682	    if (it!=entryCompressionLevels.end()) { level = it->second; }
683	    return setEntryCompressionConfig(entry, comp, level);
684	}
685	
686	bool ZipArchive::setEntryCompressionLevel(ZipEntry& entry, libzippp_uint32 level) const {
687	    if (!isOpen()) { return false; }
688	    if (!isEntryUsable(entry)) { return false; }
689	    if (mode==ReadOnly) { return false; }
690	
691	    //only the level changes: the method currently in effect for the entry is re-applied,
692	    //so a method staged through another copy of the entry is preserved
693	    libzippp_uint16 method;
694	    map<libzippp_uint64, libzippp_uint16>::const_iterator it = entryCompressionMethods.find(entry.index);
695	    if (it!=entryCompressionMethods.end()) {
696	        method = it->second;
697	    } else {
698	        /*
699	         * No method was explicitly staged on the entry during this opening: the effective
700	         * method is the one libzip will use when the changes are committed. An untouched
701	         * entry keeps its committed method (visible in the current state); an entry whose
702	         * content was added or replaced during this opening falls back to the libzip
703	         * default (its current method is merely reported as STORE by libzip, which only
704	         * means "no compression change staged" here).
705	         */
706	        struct zip_stat currentStat;
707	        struct zip_stat originalStat;
708	        zip_stat_init(&currentStat);
709	        zip_stat_init(&originalStat);
710	        bool hasCurrent = zip_stat_index(zipHandle, entry.index, ZIP_FL_ENC_GUESS, &currentStat)==0;
711	        bool hasOriginal = zip_stat_index(zipHandle, entry.index, LIBZIPPP_ORIGINAL_STATE_FLAGS, &originalStat)==0;
712	        if (hasCurrent && currentStat.comp_method!=(libzippp_uint16)ZIP_CM_STORE) {
713	            method = currentStat.comp_method;
714	        } else if (hasOriginal && originalStat.comp_method==(libzippp_uint16)ZIP_CM_STORE) {
715	            method = (libzippp_uint16)ZIP_CM_STORE; //an untouched entry stored without compression
716	        } else {
717	            method = (libzippp_uint16)ZIP_CM_DEFAULT; //new or replaced entry: libzip default
718	        }
719	    }
720	    return setEntryCompressionConfig(entry, convertCompressionFromLibzip(method), level);
721	}
