825	ZipEntry ZipArchive::getEntry(const string& name, bool excludeDirectories, bool caseSensitive, State state) const {
826	    if (isOpen()) {
827	        int flags = 0;
828	        if (excludeDirectories) { flags = flags | ZIP_FL_NODIR; }
829	        if (!caseSensitive) { flags = flags | ZIP_FL_NOCASE; }
830	        if (state==Original) { flags = flags | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
831	        else { flags = flags | ZIP_FL_ENC_GUESS; }
832	
833	        libzippp_int64 index = zip_name_locate(zipHandle, name.c_str(), flags);
834	        if (index>=0) {
835	            //the located index must be stat'd in the SAME state: locating a renamed entry
836	            //in the original state gives the original slot, whose name and size are the
837	            //original ones (using the current stat here would return the new name/length)
838	            return getEntry(index, state);
839	        } else {
840	            //name not found in the requested state
841	        }
842	    }
843	    return ZipEntry();
844	}
