882	
883	void* ZipArchive::readEntry(const ZipEntry& zipEntry, bool asText, State state, libzippp_uint64 size) const {
884	    if (!isOpen()) { return nullptr; }
885	    if (!isEntryUsable(zipEntry)) { return nullptr; }
886	
887	    //resolve the entry in the requested state: the uncompressed size and the existence of
888	    //the entry depend on the state (a replacement may be longer, shorter or empty, a deleted
889	    //entry is only readable as Original and a newly added one only as Current)
890	    libzippp_uint64 entrySize = 0;
891	    ZipEntry resolved = resolveEntry(zipEntry, state, &entrySize);
892	    if (resolved.isNull()) { return nullptr; }
893	
894	    int flag = stateFlags(state);
895	    struct zip_file* zipFile = zip_fopen_index(zipHandle, resolved.getIndex(), flag);
896	    if (zipFile) {
897	        //zero means "read the whole content" and a too big length returns all of it; the
898	        //captured zipEntry size is intentionally never used to bound the read
899	        libzippp_uint64 uisize = size==0 || size>entrySize ? entrySize : size;
900	
901	        char* data = NEW_CHAR_ARRAY(uisize+(asText ? 1 : 0))
902	        if (!data) { //allocation error
903	            zip_fclose(zipFile);
904	            return nullptr;
905	        }
906	
907	        libzippp_int64 result = zip_fread(zipFile, data, uisize);
908	        zip_fclose(zipFile);
909	
910	        //avoid buffer copy
911	        if (asText) { data[uisize] = '\0'; }
912	
913	        libzippp_int64 isize = (libzippp_int64)uisize;
914	        if (result==isize) {
915	            return data;
916	        } else { //unexpected number of bytes read => crash ?
917	            delete[] data;
918	        }
919	    } else {
920	        //unable to read the entry (e.g. it does not exist in the requested state) => crash ?
921	    }
922	
923	    return nullptr;
924	}
925	
926	void* ZipArchive::readEntry(const string& zipEntry, bool asText, State state, libzippp_uint64 size) const {
927	    //the name is interpreted in the requested state: there is no fallback to the other state
928	    //if the name does not exist in this one
929	    ZipEntry entry = getEntry(zipEntry, false, true, state);
930	    if (entry.isNull()) { return nullptr; }
931	    return readEntry(entry, asText, state, size);
932	}
933	
934	int ZipArchive::deleteEntry(const ZipEntry& entry) const {
935	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
936	    if (!isEntryUsable(entry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
937	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //deletion not allowed
938	
939	    if (entry.isFile()) {
940	        int result = zip_delete(zipHandle, entry.getIndex());
941	        if (result==0) {
942	            forgetEntryCompressionConfig(entry.getIndex());
943	            return 1;
944	        }
945	        return LIBZIPPP_ERROR_UNKNOWN; //unable to delete the entry
946	    } else {
947	        int counter = 0;
948	        vector<ZipEntry> allEntries = getEntries();
949	        vector<ZipEntry>::const_iterator eit;
950	        for(eit=allEntries.begin() ; eit!=allEntries.end() ; ++eit) {
951	            ZipEntry ze = *eit;
952	            string::size_type startPosition = ze.getName().find(entry.getName());
953	            if (startPosition==0) {
954	                int result = zip_delete(zipHandle, ze.getIndex());
955	                if (result==0) {
956	                    forgetEntryCompressionConfig(ze.getIndex());
957	                    ++counter;
958	                }
959	                else { return LIBZIPPP_ERROR_UNKNOWN; } //unable to remove the current entry
960	            }
961	        }
962	        return counter;
963	    }
964	}
