    virtual ~SimpleProgressListener(void) {}

    double firstValue;
    double lastValue;

    void progression(double p) {
        cout << "-- Progression: " << p << endl;
        if(firstValue<0) { firstValue = p; }
        lastValue = p;
    }
    int cancel() {
      return 0;
    }

