     * the content is spooled into a temporary file (created by tmpfile, hence
     * automatically deleted when the file is closed) through a fixed-size chunk
     * buffer, so the memory used by this method does not depend on the content size.
     * The temporary file is then handed to libzip (zip_source_filep), which closes it
     * when the source is freed (commit, discard, rollback or replacement): the staged
     * content therefore never depends on the stream once this method has returned.
     */
    FILE* spool = tmpfile();
    if (spool==nullptr) { return false; }

    char* chunk = NEW_CHAR_ARRAY(LIBZIPPP_DEFAULT_CHUNK_SIZE);
    if (chunk==nullptr) {
